    def calibrate(self, feedback_data: List[Dict]) -> Dict:
        bins = {}
        for item in feedback_data:
            bin_key = (item["confidence"] // 10) * 10
            if bin_key not in bins:
                bins[bin_key] = {"total": 0, "correct": 0}
            bins[bin_key]["total"] += 1
            if item["is_correct"]:
                bins[bin_key]["correct"] += 1

        calibration = {}
        for bin_key, counts in sorted(bins.items()):
            accuracy = counts["correct"] / counts["total"] if counts["total"] > 0 else 0
            calibration[bin_key] = {
                "predicted_confidence": bin_key + 5,
                "actual_accuracy": round(accuracy * 100, 1),
                "sample_count": counts["total"],
                "gap": round((bin_key + 5) - (accuracy * 100), 1),
            }

        self.calibration_map = calibration

        total_samples = sum(c["sample_count"] for c in calibration.values())
        ece = sum(
            c["sample_count"] / total_samples * abs(c["gap"])
            for c in calibration.values() if c["sample_count"] > 0
        )

        return {
            "calibration": calibration,
            "ece": round(ece, 2),
            "total_feedback": len(feedback_data),
