class RAGCache:
    def __init__(self):
        self._cache = {}  # Production'da Redis kullan

    def _make_key(self, prefix: str, *args) -> str:
        content = json.dumps(args, sort_keys=True, default=str)
        return f"{prefix}:{hashlib.md5(content.encode()).hexdigest()}"

    def get(self, key: str) -> Optional[Any]:
        if key in self._cache:
            entry = self._cache[key]
            if entry["expires_at"] > datetime.utcnow():
                return entry["value"]
            del self._cache[key]
        return None

    def set(self, key: str, value: Any, ttl_seconds: int = 3600):
        self._cache[key] = {
            "value": value,
            "expires_at": datetime.utcnow() + timedelta(seconds=ttl_seconds),
        }

    def invalidate_collection(self, collection_name: str):
        keys_to_delete = [k for k in self._cache if collection_name in k]
        for key in keys_to_delete:
            del self._cache[key]

def cached_retrieval(cache: RAGCache, ttl: int = 1800):
    def decorator(func):
        @wraps(func)
        async def wrapper(self, query, collection_name, **kwargs):
            cache_key = cache._make_key("retrieval", query, collection_name)
            cached = cache.get(cache_key)
            if cached:
                return cached
            result = await func(self, query, collection_name, **kwargs)
            cache.set(cache_key, result, ttl)
            return result
        return wrapper
    return decorator

